/**
 * What a failed Create means to the person using the form. One type for both flows; each flow
 * classifies its own transport errors into it (the project Runtime in `createSpecErrors.ts`, the demo
 * Runtime in `classifyDemoCreateFailure.ts`).
 */
export type CreateFailure =
  /** `automatic`: the rejected name was generated by the server, so the user never typed it. */
  | { kind: 'branch-exists'; automatic: boolean }
  /** `code` selects the explanation; the server's own text is never displayed. */
  | { kind: 'stale'; code: string }
  /**
   * The branch name the owner typed is not a valid Git name (the Engine's `BRANCH_NAME_INVALID`).
   * Field-level: the form flags the branch input, refreshing the options cannot help.
   */
  | { kind: 'branch-invalid' }
  | { kind: 'operation-conflict' }
  /** The project Runtime CREATE_CONFLICT: the name (slug) may be taken or the state changed. */
  | { kind: 'name-conflict' }
  | { kind: 'forbidden' }
  /** 401: the session is not authenticated (the form is kept). */
  | { kind: 'unauthenticated' }
  | { kind: 'recovery-required' }
  | { kind: 'uncertain' }
  /** The request was provably never sent (no connection at dispatch): nothing was created. */
  | { kind: 'offline' }
  /** `operationFailed`: the server finished the checked operation without a result. */
  | { kind: 'failed'; operationFailed?: true };
